import json
import os
import numpy as np


def _rows(records):
    return [row for rec in records for row in rec.get('rows', []) if isinstance(row.get('target'), (int, float))]


def _export(model_code):
    with open('model.py', 'w') as f:
        f.write(model_code)


def select_actions(public_spec, observations, memory):
    rows = _rows(observations)
    history = public_spec.get('method_results', [])
    # Reuse the confirmed archived model only when it predicts this case exactly.
    if len(rows) >= 12:
        try:
            import importlib.util
            path = 'archive/source_001/_evaluated_model/model.py'
            spec = importlib.util.spec_from_file_location('archived_predictor', path)
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            err = np.mean([(float(r['target']) - mod.predict(r))**2 for r in rows])
            if err < 1e-18:
                return {'model': path, 'lesson': 'The confirmed reset-initialized recurrence/readout predicts the paid controls and targets to floating-point precision; reuse unchanged.'}
        except Exception:
            pass
    # Acquire full-length mixed controls to expose long memory and transition behavior.
    nobs = sum(len(r.get('rows', [])) for r in observations)
    if nobs < 360:
        acts = []
        for j in range(4):
            seq = []
            for t in range(24):
                u = [-1.0, -0.5, 0.0, 0.5, 1.0][(t * (j + 2) + j) % 5]
                if j == 3:
                    u = [1.0 if t < 6 else -1.0 if t < 12 else 0.25 if t < 18 else -0.25][0]
                seq.append({'u': u})
            acts.append({'kind': 'trajectory', 'sequence': seq, 'channels': []})
        return {'actions': acts, 'question': 'Do diverse bounded long trajectories support the archived recurrence, or require a revised control-history model?'}
    # Revised finite-memory quadratic response model, trained only on current paid rows.
    code = '''import numpy as np
L=20
_COEF=None
def _x(row):
    h=row.get("history",[]); v=[float(row["features"]["u"])]
    v += [float(z["u"]) for z in h[-L:][::-1]]
    v += [0.0]*(L+1-len(v)); v=np.asarray(v[:L+1])
    return np.asarray([1.0]+list(v)+[v[i]*v[j] for i in range(L+1) for j in range(i,L+1)])
def fit(observations):
    global _COEF
    X=np.vstack([_x(r) for r in observations]); y=np.asarray([float(r["target"]) for r in observations])
    _COEF=np.linalg.lstsq(X,y,rcond=None)[0]
def predict(row):
    if _COEF is None: raise RuntimeError("fit required")
    return float(_x(row)@_COEF)
'''
    _export(code)
    return {'model': 'model.py', 'lesson': 'The inherited confirmed model did not explain this case; fit a revised reset-aware quadratic control-history model and confirm on fresh trajectories.'}

import importlib.util
import numpy as np

ARCHIVED = [
    'archive/source_000/_evaluated_model/model.py',
    'archive/source_001/_evaluated_model/model.py',
    'archive/source_002/_evaluated_model/model.py',
    'archive/source_003/_evaluated_model/model.py',
]


def _rows(records):
    return [row for rec in records for row in rec.get('rows', [])
            if isinstance(row.get('target'), (int, float))]


def _controls(row):
    hist = row.get('history', [])
    # Keep chronological order; reset history is empty at each trajectory.
    return [float(x['u']) for x in hist] + [float(row['features']['u'])]


def _load(path):
    spec = importlib.util.spec_from_file_location('candidate_' + path.split('/')[1], path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def select_actions(public_spec, observations, memory):
    rows = _rows(observations)
    # Reuse only an earlier predictor that actually explains this paid prefix.
    if rows:
        for path in ARCHIVED:
            try:
                mod = _load(path)
                mse = np.mean([(float(r['target']) - float(mod.predict(r))) ** 2 for r in rows])
                if mse < 1e-18:
                    return {'model': path, 'lesson': 'The archived predictor matches all paid rows to floating-point precision; reuse it unchanged.'}
            except Exception:
                continue

    # Otherwise estimate a revised control-only polynomial model. The feature
    # vector is reset-aware and uses up to 12 previous controls plus current u.
    if len(rows) < 12:
        return {'stop': 'Insufficient paid rows to estimate a revised control-history model.'}

    def phi(row):
        u = _controls(row)[::-1][:13]
        u += [0.0] * (13 - len(u))
        x = np.asarray(u)
        return np.r_[1.0, x, [x[i] * x[j] for i in range(13) for j in range(i, 13)]]

    X = np.vstack([phi(r) for r in rows])
    y = np.asarray([float(r['target']) for r in rows])
    coef = np.linalg.lstsq(X, y, rcond=None)[0]
    vals = repr(coef.tolist())
    model_code = '''import numpy as np\n_COEF=np.array(%s,dtype=float)\ndef predict(row):\n h=row.get("history",[])\n u=[float(x["u"]) for x in h]+[float(row["features"]["u"])]\n u=u[::-1][:13]+[0.0]*max(0,13-len(u))\n x=np.asarray(u[:13])\n f=np.r_[1.0,x,[x[i]*x[j] for i in range(13) for j in range(i,13)]]\n return float(f@_COEF)\n''' % vals
    with open('model.py', 'w') as f:
        f.write(model_code)
    return {'model': 'model.py', 'lesson': 'No archived predictor matched; fit a revised reset-aware quadratic control-history model to the paid rows and submit for fresh confirmation.'}

