            if isinstance(r.get('target'), (int, float))]


def _load(path):
    name = 'arch_' + path.split('/')[1]
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _history(row):
    return [float(v['u']) for v in row.get('history', [])] + [float(row['features']['u'])]


def _objective(p, rows):
    a, b, c = p[:3]
    q = p[3:]
    residual = []
    for row in rows:
        us = _history(row)
        m0 = 0.0
        mprev = 0.0
        uprev = 0.0
        pred = None
        for u in us:
            m = a * mprev + b * u + c * uprev
            z = np.array([m, mprev, u, uprev], dtype=float)
            phi = np.array([1., *z, z[0]*z[0], z[0]*z[1], z[0]*z[2], z[0]*z[3],
                            z[1]*z[1], z[1]*z[2], z[1]*z[3], z[2]*z[2], z[2]*z[3], z[3]*z[3]])
            pred = float(phi @ q)
            mprev, uprev = m, u
        residual.append(pred - float(row['target']))
    return np.asarray(residual)


def _fit(rows):
    # Fit a reset-initialized first-order latent filter and quadratic readout.
    best = None
    rng = np.random.default_rng(12)
    for seed in range(5):
        p0 = np.r_[rng.uniform(-.5, .8), rng.uniform(.2, 1.2), rng.uniform(-.6, .2),
                   np.zeros(15)]
        p0[3] = float(np.mean([r['target'] for r in rows]))
        opt = least_squares(_objective, p0, args=(rows,), max_nfev=2500,
                            xtol=1e-13, ftol=1e-13, gtol=1e-13)
        err = float(np.mean(_objective(opt.x, rows)**2))
        if best is None or err < best[0]:
            best = (err, opt.x)
        if err < 1e-18:
            break
    return best


def _model_text(p):
    return '''import numpy as np\nP=np.array(%r,dtype=float)\ndef predict(row):\n    us=[float(v["u"]) for v in row.get("history",[])]+[float(row["features"]["u"])]\n    a,b,c=P[:3]; q=P[3:]; m=mp=up=0.0; y=0.0\n    for u in us:\n        m=a*mp+b*u+c*up\n        z=np.array([m,mp,u,up])\n        f=np.array([1.,*z,z[0]*z[0],z[0]*z[1],z[0]*z[2],z[0]*z[3],z[1]*z[1],z[1]*z[2],z[1]*z[3],z[2]*z[2],z[2]*z[3],z[3]*z[3]])\n        y=float(f@q); mp,up=m,u\n    return y\n''' % p.tolist()


def select_actions(public_spec, observations, memory):
    rows = _rows(observations)
    if rows:
        for path in ARCHIVED:
            try:
                model = _load(path)
                errs = [float(model.predict(r)) - float(r['target']) for r in rows]
                if np.mean(np.square(errs)) < 1e-18:
                    return {'model': path, 'lesson': 'An archived predictor matches all current paid observations; reuse it unchanged.'}
            except Exception:
                pass
    if len(rows) < 24:
        return {'stop': 'Collect more paid rows before estimating a latent-state model.'}
    err, p = _fit(rows)
    if err > 1e-10:
        return {'stop': 'The reset-initialized latent-filter/readout model does not yet explain paid rows; inspect additional evidence before submission.'}
    with open('model.py', 'w') as f:
        f.write(_model_text(p))
    return {'model': 'model.py', 'lesson': 'No archived model matched; a reset-initialized latent-filter with quadratic readout explains paid rows and is submitted as a revised control-only model.'}

